INSERT INTO `faqs` VALUES (1, '如何取消订单？', '待付款和待发货状态的订单可以在订单详情页点击\"取消订单\"按钮进行取消。已发货的订单需要先申请退货。', '订单问题', 20, 1, '2026-02-04 12:33:25.430772', '2026-02-04 12:33:25.430772');
INSERT INTO `faqs` VALUES (2, '订单多久发货？', '一般情况下，订单付款后24-48小时内发货。定制商品可能需要3-5个工作日。', '订单问题', 59, 1, '2026-02-04 12:33:25.436484', '2026-02-04 12:33:25.436484');
INSERT INTO `faqs` VALUES (3, '如何查询订单物流？', '登录账户后，在\"我的订单\"中点击订单详情，可以看到物流信息和物流单号。', '订单问题', 10, 1, '2026-02-04 12:33:25.439547', '2026-02-04 12:33:25.439547');
INSERT INTO `faqs` VALUES (4, '订单可以修改收货地址吗？', '待付款状态可以修改收货地址，待发货及以上状态需要联系客服处理。', '订单问题', 34, 1, '2026-02-04 12:33:25.444108', '2026-02-04 12:33:25.444108');
INSERT INTO `faqs` VALUES (5, '部分发货怎么办？', '如果订单包含多个商品，可能会分开发货。您可以在订单详情中查看每个商品的发货状态。', '订单问题', 5, 1, '2026-02-04 12:33:25.448815', '2026-02-04 12:33:25.448815');
INSERT INTO `faqs` VALUES (6, '支持哪些支付方式？', '我们支持支付宝、微信支付、银行卡等多种支付方式。', '支付问题', 43, 1, '2026-02-04 12:33:25.453532', '2026-02-04 12:33:25.453532');
INSERT INTO `faqs` VALUES (7, '支付失败了怎么办？', '请检查账户余额是否充足，或尝试更换支付方式。如仍有问题，请联系客服。', '支付问题', 68, 1, '2026-02-04 12:33:25.457354', '2026-02-04 12:33:25.457354');
INSERT INTO `faqs` VALUES (8, '可以开发票吗？', '可以，下单时请在备注中填写发票信息（抬头、税号）。', '支付问题', 37, 1, '2026-02-04 12:33:25.462070', '2026-02-04 12:33:25.462070');
INSERT INTO `faqs` VALUES (9, '货到付款吗？', '抱歉，目前暂不支持货到付款。', '支付问题', 40, 1, '2026-02-04 12:33:25.465921', '2026-02-04 12:33:25.465921');
INSERT INTO `faqs` VALUES (10, '运费如何收取？', '单笔订单满199元免运费，不满199元收取10元运费（部分地区除外）。', '物流问题', 48, 1, '2026-02-04 12:33:25.471055', '2026-02-04 12:33:25.471055');
INSERT INTO `faqs` VALUES (11, '大概多久能收到货？', '一般情况下，发货后3-5天可收到货。偏远地区可能需要7-10天。', '物流问题', 85, 1, '2026-02-04 12:33:25.475118', '2026-02-04 12:33:25.475118');
INSERT INTO `faqs` VALUES (12, '可以指定快递吗？', '目前我们使用顺丰、中通、韵达等快递，暂不支持自选快递。', '物流问题', 24, 1, '2026-02-04 12:33:25.479314', '2026-02-04 12:33:25.479314');
INSERT INTO `faqs` VALUES (13, '发货地在哪里？', '我们的仓库位于上海、广州、北京等地，根据您的收货地址选择最近仓库发货。', '物流问题', 14, 1, '2026-02-04 12:33:25.483405', '2026-02-04 12:33:25.483405');
INSERT INTO `faqs` VALUES (14, '商品是正品吗？', '所有商品均为正品，直接从品牌方或授权代理商采购，保证质量。', '商品问题', 77, 1, '2026-02-04 12:33:25.487703', '2026-02-04 12:33:25.487703');
INSERT INTO `faqs` VALUES (15, '商品有质保吗？', '所有商品提供质保服务，具体质保期请参考商品详情页。', '商品问题', 99, 1, '2026-02-04 12:33:25.492285', '2026-02-04 12:33:25.492912');
INSERT INTO `faqs` VALUES (16, '商品适用于我的车型吗？', '请在购买前确认商品适配车型，如有疑问可咨询客服。', '商品问题', 30, 1, '2026-02-04 12:33:25.496833', '2026-02-04 12:33:25.496833');
INSERT INTO `faqs` VALUES (17, '安装视频有吗？', '部分商品提供安装教程，请在商品详情页查看。', '商品问题', 97, 1, '2026-02-04 12:33:25.500924', '2026-02-04 12:33:25.500924');
INSERT INTO `faqs` VALUES (18, '支持7天无理由退货吗？', '未安装、未使用的商品支持7天无理由退货，已安装或定制商品不支持。', '退换货问题', 86, 1, '2026-02-04 12:33:25.505761', '2026-02-04 12:33:25.505761');
INSERT INTO `faqs` VALUES (19, '如何申请退换货？', '在订单详情页点击\"申请退换货\"，填写原因并提交，客服会及时处理。', '退换货问题', 38, 1, '2026-02-04 12:33:25.509443', '2026-02-04 12:33:25.509443');
INSERT INTO `faqs` VALUES (20, '退货运费谁承担？', '质量问题退换货由我们承担运费，其他原因退换货由买家承担。', '退换货问题', 59, 1, '2026-02-04 12:33:25.513534', '2026-02-04 12:33:25.513534');
INSERT INTO `faqs` VALUES (21, '退款多久到账？', '退货确认后，1-3个工作日退款到原支付账户。', '退换货问题', 91, 1, '2026-02-04 12:33:25.518136', '2026-02-04 12:33:25.518136');
INSERT INTO `faqs` VALUES (22, '如何修改密码？', '在\"个人中心-账户安全\"中可以修改登录密码。', '账户问题', 12, 1, '2026-02-04 12:33:25.523323', '2026-02-04 12:33:25.523323');
INSERT INTO `faqs` VALUES (23, '忘记密码怎么办？', '点击登录页面的\"忘记密码\"，通过手机号验证码重置密码。', '账户问题', 19, 1, '2026-02-04 12:33:25.526904', '2026-02-04 12:33:25.526904');
INSERT INTO `faqs` VALUES (24, '如何修改收货地址？', '在\"个人中心-收货地址管理\"中可以新增、修改、删除地址。', '账户问题', 73, 1, '2026-02-04 12:33:25.530996', '2026-02-04 12:33:25.530996');
INSERT INTO `faqs` VALUES (25, '积分有什么用？', '积分可以在结算时抵扣现金，100积分=1元。', '账户问题', 60, 1, '2026-02-04 12:33:25.535548', '2026-02-04 12:33:25.535548');
INSERT INTO `faqs` VALUES (26, '如何联系客服？', '您可以通过在线客服、客服电话400-123-4567或微信公众号联系我们。', '其他', 92, 1, '2026-02-04 12:33:25.539714', '2026-02-04 12:33:25.539714');
INSERT INTO `faqs` VALUES (27, '营业时间是什么时候？', '客服工作时间：周一至周五 9:00-18:00，节假日正常休息。', '其他', 87, 1, '2026-02-04 12:33:25.544309', '2026-02-04 12:33:25.544309');
INSERT INTO `faqs` VALUES (28, '有实体店吗？', '我们在北京、上海、广州、深圳均有实体店，欢迎到店体验。', '其他', 83, 1, '2026-02-04 12:33:25.547349', '2026-02-04 12:33:25.547349');
INSERT INTO `faqs` VALUES (29, '可以上门安装吗？', '部分地区提供上门安装服务，下单前请咨询客服确认。', '其他', 13, 1, '2026-02-04 12:33:25.551450', '2026-02-04 12:33:25.552500');
INSERT INTO `faqs` VALUES (30, '产品质量有保证吗？', '所有商品均为正品，提供质保服务，质量问题支持退换货。', '其他', 62, 1, '2026-02-04 12:33:25.556689', '2026-02-04 12:33:25.556689');
INSERT INTO `messages` VALUES (1, '系统公告', '欢迎使用汽车改装件销售平台！新用户注册即送100积分优惠券。', 'announcement', 'sent', '2026-02-04 12:33:25.638395', NULL, '2026-02-04 12:33:25.638395', NULL);
INSERT INTO `messages` VALUES (2, '促销通知', '限时特惠活动开启！全场满500减50，满1000减120。快来选购吧！', 'promotion', 'sent', '2026-02-04 12:33:25.643002', NULL, '2026-02-04 12:33:25.643002', NULL);
INSERT INTO `messages` VALUES (3, '系统通知', '平台将于2024年2月1日00:00-02:00进行系统维护，期间可能影响部分功能使用。', 'system', 'sent', '2026-02-04 12:33:25.646033', NULL, '2026-02-04 12:33:25.646033', NULL);
INSERT INTO `messages` VALUES (4, '订单通知', '尊敬的何桂英，您有一个订单已发货。', 'notification', 'sent', '2026-02-04 12:33:25.651758', NULL, '2026-02-04 12:33:25.652265', 64);
INSERT INTO `messages` VALUES (5, '订单通知', '尊敬的何静，您有一个订单已发货。', 'notification', 'sent', '2026-02-04 12:33:25.656382', NULL, '2026-02-04 12:33:25.656382', 73);
INSERT INTO `messages` VALUES (6, '订单通知', '尊敬的吴霞，您有一个订单已发货。', 'notification', 'sent', '2026-02-04 12:33:25.660965', NULL, '2026-02-04 12:33:25.660965', 68);
INSERT INTO `messages` VALUES (7, '订单通知', '尊敬的马洋，您有一个订单已发货。', 'notification', 'sent', '2026-02-04 12:33:25.664863', NULL, '2026-02-04 12:33:25.664863', 58);
INSERT INTO `messages` VALUES (8, '订单通知', '尊敬的王霞，您有一个订单已发货。', 'notification', 'read', '2026-02-04 12:33:25.669471', '2026-02-05 13:03:51.162620', '2026-02-04 12:33:25.669471', 65);
INSERT INTO `modification_cases` VALUES (1, '本田NSX超级跑车改装 - 001', '这是一份关于奔驰的改装案例，展示了专业的改装工艺和显著的性能提升。', '排气系统采用全段不锈钢排气管，声浪低沉有力，不扰民。配合高流量三元催化，排气更加顺畅。', 'https://picsum.photos/seed/case0/800/600.jpg', '赵工程师', 'published', 601, 50, '2026-01-11 21:12:22.214229', '2026-02-04 12:33:25.214229', '2026-02-04 12:33:25.214229');
INSERT INTO `modification_cases` VALUES (2, '高尔夫GTI Stage 2改装 - 002', '这是一份关于宝马的改装案例，展示了专业的改装工艺和显著的性能提升。', '外观方面安装了前唇、侧裙和后扰流板，配合悬挂系统的降低，整体姿态更加运动。轮毂升级为19寸锻造轮毂，搭配高性能轮胎，提升了操控性能。', 'https://picsum.photos/seed/case1/800/600.jpg', '李工', 'published', 2297, 46, '2025-02-10 11:46:22.218317', '2026-02-04 12:33:25.218317', '2026-02-04 12:33:25.218317');
INSERT INTO `modification_cases` VALUES (3, '奥迪S3动力提升 - 003', '这是一份关于奔驰的改装案例，展示了专业的改装工艺和显著的性能提升。', '悬挂系统更换为绞牙避震，可调节高度和阻尼。降低了车身高度，提升了过弯稳定性，日常驾驶舒适性也保持良好。', 'https://picsum.photos/seed/case2/800/600.jpg', '王师傅', 'published', 3508, 19, '2025-07-14 15:43:23.222945', '2026-02-04 12:33:25.222945', '2026-02-04 12:33:25.222945');
INSERT INTO `modification_cases` VALUES (4, '马自达MX-5敞篷改装 - 004', '这是一份关于宝马的改装案例，展示了专业的改装工艺和显著的性能提升。', '悬挂系统更换为绞牙避震，可调节高度和阻尼。降低了车身高度，提升了过弯稳定性，日常驾驶舒适性也保持良好。', 'https://picsum.photos/seed/case3/800/600.jpg', '赵工程师', 'published', 4027, 9, '2025-02-05 03:23:52.227001', '2026-02-04 12:33:25.227001', '2026-02-04 12:33:25.227001');
INSERT INTO `modification_cases` VALUES (5, '思域Type-R赛道化改装 - 005', '这是一份关于宝马的改装案例，展示了专业的改装工艺和显著的性能提升。', '外观方面安装了前唇、侧裙和后扰流板，配合悬挂系统的降低，整体姿态更加运动。轮毂升级为19寸锻造轮毂，搭配高性能轮胎，提升了操控性能。', 'https://picsum.photos/seed/case4/800/600.jpg', '赵工程师', 'published', 4351, 14, '2025-02-18 10:40:13.231643', '2026-02-04 12:33:25.231643', '2026-02-04 12:33:25.231643');
